import { createHash } from 'node:crypto';
export type JaAffirmationProblem = {
  slug: string;
  title: string;
  shortTitle: string;
  metaDescription: string;
  intro: string;
  affirmations: string[];
  /** Optional longer body paragraphs (why this feeling shows up). */
  whyItHappens?: string[];
  /** Optional ~2-minute practice block. */
  practice?: { heading: string; steps: string[] };
  /** Optional closing / medical disclaimer paragraph. */
  closing?: string;
  /**
   * Optional GEO fields (same pattern as the EN guides). When set, the page
   * uses the exact phrase as H1, shows a quotable direct answer at the top,
   * and uses these hand-written FAQs (+ FAQPage JSON-LD) instead of the
   * auto-generated fallback.
   */
  h1?: string;
  /** Usually three short paragraphs AI/search can quote. */
  directAnswer?: string[];
  faq?: JaAffirmationFaq[];
  /** True EN translation slug under /affirmation-app/a/* when one exists. */
  enSlug?: string;
  /** True ES translation slug under /affirmation-app/es/a/* when one exists. */
  esSlug?: string;
};

export const JA_AFFIRMATION_APP_STORE_BASE =
  'https://apps.apple.com/jp/app/id6755129214';

export function jaAffirmationAppStoreUrl(slug: string): string {
  const url = new URL(JA_AFFIRMATION_APP_STORE_BASE);
  url.searchParams.set('utm_source', 'aniccaai');
  url.searchParams.set('utm_medium', 'seo');
  url.searchParams.set('utm_campaign', 'anicca_ja_problem');
  url.searchParams.set('utm_content', slug);
  url.searchParams.set('pt', '93486075');
  // App Store campaign tokens must be <= 30 chars; hash long identities to keep them unique.
  const identity = `seo_ja_${slug}`;
  const campaign = identity.length <= 30
    ? identity
    : `${identity.slice(0, 13)}-${createHash('sha256').update(identity, 'utf8').digest('hex').slice(0, 16)}`;
  url.searchParams.set('ct', campaign);
  url.searchParams.set('mt', '8');
  return url.toString();
}

